window.__posterData({"id": "axel-hedman", "name": "Axel Hedman", "folder": "Axel_Hedman _DIK_HT26-1", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "// I used Gemini\n\n// 1. Prompt: “Refactor the code without changing functionality”. It organized and cleaned up the code and simplified the numbers in \"shadowBlur\". It also removed the repeating blocks in \"drawRows\". I can understand the changes, and even if I can't remember if we went through this in class, I still think that it is simple enough that we would be able to figure it out with enough time. The AI also changed the comments. \n\n// 2. Prompt: \"When I press the mouse the speed changes randomly both when I press and let go. I only want the speed to change when I let go of the mouse. The speed should always change when the mouse is clicked and never stay the same\". I also gave the prompt: \"Make the speed slow down while pressing the mouse\" and changed the speed while the mouse is pressed to zero. \n\n// 3. Prompt: \"Suggest and implement 1 additional feature to this poster, something that YOU think is fun, such as an animation loop, interactive component, or something else. Use your best judgement given the current style and aesthetic\". It made the text in \"drawRows\" move up and down like waves. \n\nconst speedOptions = [40, 70, 100, 130, 160]; // Array with different speed options\nlet img; // Background image variable\nlet Width = 0; // Width of the text\nlet x = 0; // X position starting at 0\nlet speed = 40; // Initial speed\nlet currentSpeed = 40; // Current speed for smooth acceleration/deceleration\n\nasync function setup() {\n  createCanvas(600, 800); // Create canvas\n  textFont('Courier New'); // Set text font\n  \n  img = await loadImage('Bilder/raveposter.jpg'); // Load background image\n\n  Width = textWidth('rave.rave.rave.rave.rave.rave.'); // Calculate text width\n  console.log('Text Width: ' + Width);\n}\n\nfunction draw() {\n  image(img, 0, 0, 600, 800); // Draw background image\n  filter(BLUR, 2); // Apply blur filter\n\n  drawRows(); // Draw the moving rave text rows with wave effect\n  drawText(); // Draw static interface text and date box\n\n  // Determine target speed: slow down when mouse is pressed, otherwise use normal speed\n  let targetSpeed = mouseIsPressed ? 0 : speed; // I asked the AI to slow down the text while the mouse is pressed. I'm really happy with the result because it looks like the text freezes. The freezing effect complements the color change to blue. I tried to make this effect without AI but failed, so I'm glad my vision finally came to life. \n  \n  // Smoothly interpolate currentSpeed towards targetSpeed for a fluid slow-motion effect\n  currentSpeed = lerp(currentSpeed, targetSpeed, 0.1); \n\n  // Move text horizontally\n  x += currentSpeed; \n  if (x > Width) {\n    console.log('X: ' + x);\n    x = -Width; // Reset position to loop smoothly from the left\n  }\n\n  // Invert colors only while the mouse is pressed down\n  if (mouseIsPressed) {\n    filter(INVERT);\n  }\n}\n\n// Triggered once when you let go of the mouse button\nfunction mouseReleased() {\n  // Filter out the current speed so it always picks a different option\n  const availableOptions = speedOptions.filter(s => s !== speed);\n  speed = random(availableOptions);\n  console.log('New Speed: ' + speed); // This is something that I asked AI to do because I failed when I tried to do it by myself. Before I made this change the function looked weird and laggy in a bad way. I think I would be able to accomplish this given enough time, but the AI did a really good job of solving the issue. \n}\n\nfunction drawRows() {  \n  textAlign(CENTER, CENTER);\n  \n  drawingContext.shadowBlur = 50; // Shadow blur effect\n  drawingContext.shadowColor = 'black'; // Shadow color\n  \n  textSize(180);\n  textStyle(BOLD);\n\n  // Configuration for each row to eliminate code repetition\n  const rows = [\n    { fill: 'black', y: 100, xOffset: 0 },\n    { fill: '#663220', y: 200, xOffset: 400 },\n    { fill: '#b25838', y: 300, xOffset: 800 },\n    { fill: '#ff7f50', y: 400, xOffset: 1200 } // As it says, the AI restructured the \"rows\" to eliminate repetition. OBS my comment\n  ];\n\n  const raveString = 'rave.rave.rave.rave.rave.rave.rave.rave.';\n\n  // Draw each text row using the configuration array with a liquid sine-wave offset\n  for (let i = 0; i < rows.length; i++) {\n    let row = rows[i];\n    \n    // Calculate a smooth vertical wave offset using sin() and frameCount\n    // Each row has a slightly phase-shifted wave for a cascading fluid effect\n    let waveOffset = sin(frameCount * 0.05 + i * 0.8) * 15;\n    \n    fill(row.fill);\n    text(raveString, x + row.xOffset, row.y + waveOffset); // I like the change because the movement makes the poster feel more alive and energetic. It works really well with the psychedelic aesthetic. When I first saw my classmates' work I realized that I wanted more energy to mimic the rave-vibe. I did not think that the wave-movement would suit the poster until I saw it in action and now I'm happy that I got to see it. \n  }\n}\n\nfunction drawText() {  \n  // Date background box\n  fill('white');\n  rect(570, 570, -270, -40);\n  \n  // Date text\n  textAlign(RIGHT);\n  textSize(24);\n  textStyle(NORMAL);\n  fill('black');\n  text('date : 18/11/2026', 550, 550);\n\n  // Author watermark\n  textAlign(LEFT);\n  textSize(12);\n  textStyle(NORMAL);\n  fill('white');\n  text('made by axel hedman', 50, 750);\n}\n\n// Overall, I'm happy with the help I got from the AI. The result matched my vision, and I was able to improve some things I didn't like in the original version. If I got to do one last improvement, I would remove the lag that can appear when you freeze the text. I have tried to solve it, both by myself and with AI, but could not find a solution that looked good enough. ", "assets": {"Bilder/raveposter.jpg": {"mime": "image/webp", "b64": ""}}});
